import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import {
  BackendClient,
  FixtureTransport,
  joinModelDetails,
  normalizeCapabilities,
  normalizeCatalog,
  normalizeContexts,
  normalizeContextEvidence,
  normalizeLogPage,
  normalizeOperation,
  normalizeShareUsage,
} from "../../src/console/backend/index.ts";

// This file never imports Python/production services. Its only input is a
// sanitized fixture explicitly generated by the parent from isolated handlers.
const fixturePath =
  process.argv[2] ??
  fileURLToPath(
    new URL(
      "../../../tests/fixtures/frontend_contract_rev25.json",
      import.meta.url
    )
  );
const fixture = JSON.parse(await readFile(fixturePath, "utf8"));
assert.equal(
  fixture.metadata?.fixture,
  true,
  "fixture metadata must explicitly identify simulated data"
);
assert.equal(fixture.metadata.sourceHashEncoding, "utf8-lf");
// Mirrors the generator's `names` (contract §10.2): the newly published action
// shapes come from console/share_actions.py / console/share_production.py (Rev9).
const sourceNames = [
  "model_sync/sync.py",
  "model_sync/sync_core.py",
  "console/model_actions.py",
  "console/adapters.py",
  "console/operations.py",
  "share/metering.py",
  "console/stats.py",
  "console/log_reader.py",
  "usagesrv.py",
  "console/share_actions.py",
  "console/share_production.py",
  "console/gateway_connection.py",
];
assert.deepEqual(
  Object.keys(fixture.metadata.sourceHashes).sort(),
  [...sourceNames].sort()
);
for (const name of sourceNames) {
  const source = await readFile(
    new URL(`../../../${name}`, import.meta.url),
    "utf8"
  );
  const hash = createHash("sha256")
    .update(source.replaceAll("\r\n", "\n"), "utf8")
    .digest("hex");
  assert.equal(
    fixture.metadata.sourceHashes[name],
    hash,
    `${name}: fixture is stale; regenerate it from the current handlers`
  );
}
const capabilities = normalizeCapabilities(fixture.actions);
const catalog = normalizeCatalog(fixture.catalog);
assert.deepEqual(
  Object.keys(fixture.scoped_catalog.catalogs),
  ["um"],
  "scoped refresh excludes unselected sources"
);
assert.ok(
  fixture.scoped_catalog.catalogs.um,
  "scoped refresh keeps the selected source"
);
const contexts = normalizeContexts(fixture.context_overrides);
const evidence = normalizeContextEvidence(fixture.context_probe_preview);
const details = joinModelDetails(catalog, contexts, evidence);
const share = normalizeShareUsage(fixture.share_usage);
const logs = normalizeLogPage(fixture.log_entries);
assert.equal(fixture.log_overview.coverage.full_history, false);
assert.equal(fixture.log_overview.coverage.targets_total, 3);
assert.equal(fixture.log_overview.coverage.targets_read, 2);
assert.ok(
  fixture.log_overview.rows.some(
    (row) => row.category === "errors" && row.level === "WARNING"
  )
);
assert.ok(
  fixture.log_overview.targets.some(
    (row) => row.status === "unconfigured" && row.rows === null
  )
);
const fixtureTransport = new FixtureTransport({
  name: "generated-python-contract",
  actions: capabilities,
  reads: {
    "/share-usage": { status: 200, body: fixture.share_usage },
    "/log-entries": { status: 200, body: fixture.log_entries },
  },
  operations: {
    "model.catalog": [{ result: fixture.catalog }],
    "model.context_overrides": [{ result: fixture.context_overrides }],
    "model.context_probe_preview": [{ result: fixture.context_probe_preview }],
  },
});
let time = 0;
const client = new BackendClient(fixtureTransport, {
  now: () => time,
  sleep: async (ms) => {
    time += ms;
  },
});
assert.deepEqual(await client.readCatalog(), catalog);
assert.deepEqual(await client.readContexts(), contexts);
assert.deepEqual(await client.readContextEvidence(), evidence);
assert.deepEqual((await client.readShareUsage()).value, share);
assert.deepEqual(
  await client.readLogs({ source: "fixture", category: "runtime" }),
  logs
);
assert.ok(fixtureTransport.calls.every((call) => !call.path.includes("://")));
assert.equal(
  fixtureTransport.calls.filter((call) => call.method === "POST").length,
  3
);

assert.deepEqual(Object.keys(fixture.share_usage).sort(), [
  "checkedAt",
  "coverage",
  "filters",
  "keys",
  "requests",
  "results",
  "unattributed",
]);
// D18-2: the four real outcomes are separate counters. `unknown` is never
// merged into `success`, and the coverage block repeats how much of the total the
// page cannot classify.
assert.deepEqual(share.results, {
  success: 3,
  failed: 1,
  cancelled: 0,
  unknown: 2,
  total: 6,
  unknownResult: 2,
});
// The read face echoes the whitelisted filters it applied (r14 additive). This
// fixture is the unfiltered read (complete history), so every filter keeps its
// default and the normalized view must not invent a narrowing.
assert.deepEqual(share.filters, {
  window: "all",
  key: null,
  model: null,
  result: null,
});
// Cost/price fields were retired with #30: the raw share-usage payload carries
// no amount, and the normalized view leaves every amount null.
const usageRow = share.keys.find((row) => row.keyId === "fixture-key");
for (const field of ["costCny", "knownCostCny", "estimatedCostCny"]) {
  assert.equal(usageRow[field], null);
}
assert.equal(usageRow.coverage.costCnyPartial, null);
assert.equal(usageRow.models[0].costCny, null);
assert.equal(usageRow.days[0].costCny, null);
assert.equal(share.unattributed.costCny, null);
assert.equal(share.unattributed.knownCostCny, null);
assert.equal(share.unattributed.estimatedCostCny, null);
assert.equal(share.unattributed.undated, null);
assert.equal(share.coverage.unpricedRequests, undefined);
assert.equal(share.coverage.priceFn, undefined);
assert.equal(share.coverage.priceVersions, undefined);
assert.equal(share.coverage.costCnyPartial, undefined);
assert.equal(share.coverage.rateFn, undefined);
console.log(
  JSON.stringify(
    {
      fixture: true,
      input: fixturePath,
      actions: capabilities.length,
      models: catalog.models.length,
      joinedModels: details.length,
      keys: share.keys.length,
      logEvents: logs.events.length,
      simulatedOperations: 5,
      liveRequests: 0,
      result: "PASS",
    },
    null,
    2
  )
);
